	allegiance = "Elfos Noturnos · Darnassus",
	aliases = { "Gilshalan" },
	sections = {
		{
			title = "Resumo",
			text = [=[Gilshalan Windwalker veio a {link:shadowglen}Umbravale{/link} para estudar as aranhas webwood da Caverna Fionumbra. Elas são primas de uma raça muito menor, e ele acredita que a Árvore do Mundo as transformou. Ele quer que seu veneno e seus ovos sejam levados a {link:darnassus}Darnassus{/link}, onde poderá compará-los com os de suas parentes menores. É honesto o bastante para admitir que uma aranha gigante viva seria mais do que ele conseguiria controlar.]=],
		},
		{
			title = "Importância",
