		},
		{
			title = "Feitos",
			text = [=[• Recolhe o veneno e os ovos das aranhas webwood.
• Envia os recém-chegados a {link:tenaron-stormgrip}Tenaron Stormgrip{/link}, no alto de {link:aldrassil}Aldrassil{/link}.]=],
		},
	},
