Translate("ptBR", "gnarlpine-furbolgs", {
	title = "Pelursos Masca-pinho",
	aliases = { "Masca-pinho", "tribo Masca-pinho" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Masca-pinho são uma tribo de {link:furbolgs}pelursos{/link} que vivia nas colinas de {link:teldrassil}Teldrassil{/link} como amigos pacíficos dos elfos noturnos. Abandonaram seus antigos lares e se reuniram sob seu chefe, {link:ursal-the-mauler}Ursal, o Estraçalhador{/link}, e agora atacam os mesmos protetores em quem um dia confiaram.]=],
		},
		{
			title = "A Queda da Tribo",
			text = [=[A dríade {link:tarindrella}Tarindrella{/link} acredita que só o musgo vil poderia causar tal mudança. {link:ursal-the-mauler}Ursal{/link} usa seus poderes para enlouquecer seu povo. Os totens deixados em seus acampamentos abandonados contam mais. Os Masca-pinho começaram a sonhar com uma grande sombra que os destruiria. O medo virou fúria, e a sombra de seus sonhos se tornou seus amigos elfos.]=],
		},
		{
			title = "Feitos da Loucura",
			text = [=[• Emboscaram o guardião {link:gaerolas-talvethren}Gaerolas Talvethren{/link} e saquearam o {link:starbreeze-village}Vilarejo Brisastral{/link}.
• Invadiram a {link:ban-ethil-barrow-den}Gruta de Ban'ethil{/link}, e seus xamãs aprenderam a separar o espírito de um druida adormecido de seu corpo.
• Atacam a estrada para {link:darnassus}Darnassus{/link} e as patrulhas nas {link:pools-of-arlithrien}Águas de Arlithrien{/link}.
• Seu místico Ferocitas, o Devorador de Sonhos, roubou uma esmeralda que tirava poder do Sonho.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Ninguém sabe ainda de onde veio o musgo vil, nem se os pelursos podem ser curados.]=],
		},
	},
})

Translate("ptBR", "corruption-of-teldrassil", {
	title = "Corrupção de Teldrassil",
	sections = {
		{
			title = "Resumo",
			text = [=[A corrupção de {link:teldrassil}Teldrassil{/link} é a doença que se espalhou pela nova Árvore do Mundo desde que ela cresceu. As sacerdotisas e os druidas veem seus sinais por toda parte: nas feras, nas plantas, nos pelursos e até no solo.]=],
		},
		{
			title = "Sinais",
			text = [=[• Feras estranhas surgem do próprio chão da árvore, e os arvoretos ficam irados e inchados de tumores venenosos.
• Um musgo vil contamina os capetas de {link:shadowglen}Umbravale{/link}, as harpias da {link:the-oracle-glade}Clareira do Oráculo{/link} e os pelursos {link:gnarlpine-furbolgs}Masca-pinho{/link}.
• O {link:satyrs}sátiro{/link} Xethorr, o Perverso, deformou as aranhas da árvore, e outros sátiros profanam seus poços lunares.
• {link:lady-sathrah}Lady Sathrah{/link}, uma aranha amada por Eluna, enlouqueceu.
• Plantas de terras distantes brotam na árvore e reagem de forma estranha a seu solo.]=],
		},
		{
			title = "A Questão da Causa",
			text = [=[{link:corithras-moonrage}Corithras Moonrage{/link} atribui muitos dos males da árvore a seu crescimento sem a bênção de Nozdormu e {link:alexstrasza}Alexstrasza{/link}. {link:fandral-staghelm}Fandral Staghelm{/link} carrega o fardo de encontrar um remédio e teme que sua obra nunca esteja terminada. Os druidas da {link:moonglade}Clareira da Lua{/link} e os de {link:darnassus}Darnassus{/link} desconfiam uns dos outros, e a corrupção contínua em nada ajuda a aliviar essa desconfiança.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica aponta ainda a origem do musgo vil, nem explica como a mácula entrou pela primeira vez na árvore.]=],
		},
	},
})
